<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';
use School\Core\SchoolAuth;
use School\Core\SchoolDatabase;
SchoolAuth::requireLogin();$user=SchoolAuth::user();$role=school_current_role($user);$reportId=(int)($_GET['id']??0);if(!$reportId){http_response_code(404);exit('Report card not found.');}$pdo=SchoolDatabase::connection();$q=$pdo->prepare("SELECT rc.id,rc.student_id,rc.report_number,rc.published_at,snap.payload_json,snap.branding_snapshot_json,snap.checksum FROM report_cards rc JOIN report_card_snapshots snap ON snap.report_card_id=rc.id WHERE rc.id=:id AND rc.published_at IS NOT NULL");$q->execute(['id'=>$reportId]);$report=$q->fetch();if(!$report){http_response_code(404);exit('Report card not found.');}
if(!hash_equals((string)$report['checksum'],hash('sha256',(string)$report['payload_json'].(string)$report['branding_snapshot_json']))){http_response_code(500);exit('The saved report snapshot failed its integrity check.');}
$payload=json_decode($report['payload_json'],true,512,JSON_THROW_ON_ERROR);$brand=json_decode($report['branding_snapshot_json'],true,512,JSON_THROW_ON_ERROR);$studentId=(int)$report['student_id'];
if($role==='parent_guardian')$allowed=SchoolAuth::hasPermission('results.view_published')&&SchoolAuth::can('portal.child',['student_id'=>$studentId]);
elseif($role==='student')$allowed=SchoolAuth::hasPermission('results.view_published')&&SchoolAuth::can('portal.self',['student_id'=>$studentId]);
elseif(in_array($role,['class_teacher','subject_teacher'],true))$allowed=SchoolAuth::can('results.review',['class_group_id'=>(int)$payload['student']['class_group_id'],'academic_year_id'=>(int)$payload['academic_year']['id']]);
else $allowed=SchoolAuth::hasPermission('results.publish')||SchoolAuth::hasPermission('school.manage')||(SchoolAuth::hasPermission('results.review')&&!in_array($role,['parent_guardian','student'],true));
if(!$allowed){http_response_code(403);exit('Report card access is not permitted.');}
$pageTitle='Report card '.$report['report_number'];$items=$payload['results']??[];$total=(float)($payload['total_mark']??0);$max=(float)($payload['maximum_mark']??0);$average=$payload['average_percentage']??null;
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?> | <?= e($brand['name']??'School Management') ?></title><style>
:root{--green:#075c47;--green-dark:#063328;--gold:#c9a447;--ink:#202a29;--muted:#64716d;--line:#dce5e1;--wash:#f5f8f6}*{box-sizing:border-box}body{margin:0;background:#edf2ef;color:var(--ink);font:14px/1.45 Arial,Helvetica,sans-serif}.report{width:210mm;min-height:297mm;margin:24px auto;background:#fff;padding:17mm 16mm 14mm;box-shadow:0 10px 35px #173d3020;position:relative}.top-line{height:7px;background:linear-gradient(90deg,var(--green) 0 76%,var(--gold) 76%);position:absolute;left:0;right:0;top:0}.school-head{display:flex;justify-content:space-between;gap:24px;align-items:flex-start;border-bottom:1px solid var(--line);padding-bottom:17px}.school-name{color:var(--green-dark);font-size:24px;font-weight:700;letter-spacing:.3px;margin:0}.motto{color:var(--muted);font-style:italic;margin-top:4px}.school-contact{text-align:right;color:var(--muted);font-size:11px;white-space:pre-line}.title-row{display:flex;justify-content:space-between;align-items:center;margin:22px 0 14px}.title-row h1{color:var(--green);font-size:20px;letter-spacing:1.5px;text-transform:uppercase;margin:0}.report-no{color:var(--muted);font-size:11px}.student-box{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:0;background:var(--wash);border:1px solid var(--line);border-radius:8px;overflow:hidden;margin-bottom:18px}.student-box div{padding:10px 12px;border-right:1px solid var(--line);border-bottom:1px solid var(--line)}.student-box div:nth-child(3n){border-right:0}.student-box div:nth-last-child(-n+3){border-bottom:0}.label{display:block;text-transform:uppercase;letter-spacing:.7px;color:var(--muted);font-size:9px;margin-bottom:4px}.value{font-weight:600}.section-title{color:var(--green-dark);font-size:12px;text-transform:uppercase;letter-spacing:1px;margin:18px 0 8px}.marks{width:100%;border-collapse:collapse}.marks th{background:var(--green);color:#fff;padding:9px 10px;text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.6px}.marks th:last-child,.marks td:last-child{text-align:right}.marks td{border-bottom:1px solid var(--line);padding:10px}.marks tbody tr:nth-child(even){background:#fafcfb}.summary{display:flex;justify-content:flex-end;margin-top:14px}.summary-box{width:270px;border:1px solid var(--line);border-radius:8px;padding:10px 13px}.summary-line{display:flex;justify-content:space-between;padding:4px 0}.summary-line.average{border-top:1px solid var(--line);margin-top:4px;padding-top:9px;color:var(--green);font-size:16px;font-weight:700}.note{margin-top:26px;padding:12px 14px;background:#fcfaf4;border-left:3px solid var(--gold);color:#58625f;font-size:11px}.signature-row{display:grid;grid-template-columns:1fr 1fr;gap:60px;margin:48px 6px 0}.sign{border-top:1px solid #7f8a85;padding-top:7px;color:var(--muted);font-size:10px}.footer{position:absolute;bottom:11mm;left:16mm;right:16mm;border-top:1px solid var(--line);padding-top:8px;display:flex;justify-content:space-between;color:var(--muted);font-size:9px}.toolbar{max-width:210mm;margin:14px auto;display:flex;gap:8px;justify-content:flex-end}.btn{border:0;border-radius:6px;padding:10px 14px;background:var(--green);color:#fff;font-weight:600;cursor:pointer}.btn.secondary{background:#fff;color:var(--green);border:1px solid var(--line)}
