</style></head><body><div class="toolbar"><button class="btn secondary" onclick="history.back()">Back</button><button class="btn" onclick="window.print()">Print / Save as PDF</button></div><article class="report"><div class="top-line"></div><header class="school-head"><div><h2 class="school-name"><?= e($brand['name']??'School Management') ?></h2><?php if(!empty($brand['motto'])): ?><div class="motto"><?= e($brand['motto']) ?></div><?php endif; ?></div><div class="school-contact"><?= e(implode("\n",array_filter([$brand['address']??null,$brand['phone']??null,$brand['email']??null,$brand['website']??null]))) ?></div></header><div class="title-row"><h1>Academic Report Card</h1><div class="report-no">Report no. <strong><?= e($report['report_number']) ?></strong></div></div><section class="student-box"><div><span class="label">Student name</span><span class="value"><?= e($payload['student']['name']??'') ?></span></div><div><span class="label">Admission number</span><span class="value"><?= e($payload['student']['admission_number']??'') ?></span></div><div><span class="label">Class</span><span class="value"><?= e($payload['student']['class']??'') ?></span></div><div><span class="label">Academic year</span><span class="value"><?= e($payload['academic_year']['name']??'') ?></span></div><div><span class="label">Term</span><span class="value"><?= e($payload['term']['name']??'') ?></span></div><div><span class="label">Assessment</span><span class="value"><?= e($payload['examination']['name']??'') ?></span></div></section><h3 class="section-title">Subject performance</h3><table class="marks"><thead><tr><th>Subject</th><th>Mark</th><th>Maximum</th><th>Percent</th><th>Grade</th></tr></thead><tbody><?php foreach($items as $item): $pct=(float)$item['max_mark']>0?(float)$item['mark']*100/(float)$item['max_mark']:0; ?><tr><td><?= e($item['subject_name']) ?></td><td><?= e(num($item['mark'])) ?></td><td><?= e(num($item['max_mark'])) ?></td><td><?= e(number_format($pct,1)).'%' ?></td><td><?= e($item['grade']?:'-') ?></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="5">No results in this snapshot.</td></tr><?php endif; ?></tbody></table><div class="summary"><div class="summary-box"><div class="summary-line"><span>Total marks</span><strong><?= e(num($total)).' / '.e(num($max)) ?></strong></div><div class="summary-line average"><span>Average</span><strong><?= $average===null?'-':e(number_format((float)$average,1)).'%' ?></strong></div></div></div><div class="note">This report reflects the results approved and published by the school. Published report cards are saved as an immutable snapshot. Contact the school office for corrections.</div><div class="signature-row"><div class="sign">Class teacher</div><div class="sign">Head teacher</div></div><footer class="footer"><span><?= e($brand['name']??'School Management') ?></span><span>Published <?= e(formatDate(substr((string)$report['published_at'],0,10))) ?> · <?= e($report['report_number']) ?></span></footer></article></body></html>
